solution.solution.py:
def as_gib(size_in_bytes):
    return round(size_in_bytes / 1024 ** 3, 1)

def download_seconds(megabytes, megabits):
    return megabytes * 8 / megabits

unitTests:
@test("the 1 TB drive")
def _():
    check_eq(as_gib(1_000_000_000_000), 931.3)
    check_eq(as_gib(500_000_000_000), 465.7)

@test("exact powers of two")
def _():
    check_eq(as_gib(1024 ** 3), 1.0)
    check_eq(as_gib(16 * 1024 ** 3), 16.0)

@test("downloads")
def _():
    check_near(download_seconds(5000, 100), 400.0)
    check_near(download_seconds(12.5, 100), 1.0)
    check_near(download_seconds(700, 50), 112.0)

